CREATE SCHEMA IF NOT EXISTS arena_competition;
SET LOCAL search_path TO arena_competition,public;
CREATE TABLE IF NOT EXISTS events(id TEXT PRIMARY KEY,name TEXT NOT NULL,status TEXT NOT NULL,config TEXT NOT NULL,paused BIGINT NOT NULL DEFAULT 0,snapshot TEXT,created BIGINT NOT NULL);
    CREATE TABLE IF NOT EXISTS teams(id TEXT PRIMARY KEY,event TEXT NOT NULL REFERENCES events(id),name TEXT NOT NULL,seed BIGINT NOT NULL,repo TEXT,UNIQUE(event,name),UNIQUE(event,seed));
    CREATE TABLE IF NOT EXISTS members(event TEXT NOT NULL REFERENCES events(id),"user" TEXT NOT NULL,team TEXT NOT NULL REFERENCES teams(id),student TEXT NOT NULL,PRIMARY KEY(event,"user"),UNIQUE(event,student));
    CREATE TABLE IF NOT EXISTS invites(hash TEXT PRIMARY KEY,event TEXT NOT NULL REFERENCES events(id),team TEXT NOT NULL REFERENCES teams(id),email TEXT NOT NULL,student TEXT NOT NULL,expires BIGINT NOT NULL,redeemed BIGINT NOT NULL DEFAULT 0);
    CREATE TABLE IF NOT EXISTS submissions(id TEXT PRIMARY KEY,team TEXT NOT NULL REFERENCES teams(id),source TEXT NOT NULL,sha TEXT NOT NULL,status TEXT NOT NULL,verdict TEXT,provenance TEXT,created BIGINT NOT NULL,UNIQUE(team,sha));
    CREATE TABLE IF NOT EXISTS entries(event TEXT NOT NULL REFERENCES events(id),team TEXT NOT NULL REFERENCES teams(id),submission TEXT NOT NULL REFERENCES submissions(id),group_no BIGINT NOT NULL,seed BIGINT NOT NULL,PRIMARY KEY(event,team));
    CREATE TABLE IF NOT EXISTS series(rowid BIGSERIAL UNIQUE,id TEXT PRIMARY KEY,event TEXT NOT NULL REFERENCES events(id),stage TEXT NOT NULL,round BIGINT NOT NULL,group_no BIGINT,a TEXT NOT NULL REFERENCES teams(id),b TEXT NOT NULL REFERENCES teams(id),winner TEXT,status TEXT NOT NULL DEFAULT 'queued',extra BIGINT NOT NULL DEFAULT 0);
    CREATE TABLE IF NOT EXISTS games(rowid BIGSERIAL UNIQUE,completed BIGINT NOT NULL DEFAULT 0,winner TEXT,id TEXT PRIMARY KEY,series TEXT NOT NULL REFERENCES series(id),ordinal BIGINT NOT NULL,p1 TEXT NOT NULL REFERENCES teams(id),p2 TEXT NOT NULL REFERENCES teams(id),result TEXT,UNIQUE(series,ordinal));
    CREATE TABLE IF NOT EXISTS jobs(id TEXT PRIMARY KEY,event TEXT NOT NULL REFERENCES events(id),kind TEXT NOT NULL,subject TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'queued',lease TEXT,"until" BIGINT NOT NULL DEFAULT 0,attempts BIGINT NOT NULL DEFAULT 0,worker TEXT,next BIGINT NOT NULL DEFAULT 0,payload TEXT NOT NULL,result_hash TEXT,created BIGINT NOT NULL,UNIQUE(kind,subject));
    CREATE INDEX IF NOT EXISTS jobs_ready ON jobs(status,next,kind,created);
    CREATE INDEX IF NOT EXISTS submissions_team ON submissions(team,created);
    CREATE INDEX IF NOT EXISTS series_event ON series(event,stage,round);
    CREATE TABLE IF NOT EXISTS workers(id TEXT PRIMARY KEY,seen BIGINT NOT NULL,runtime TEXT NOT NULL);
    CREATE TABLE IF NOT EXISTS audit(id BIGSERIAL PRIMARY KEY,actor TEXT NOT NULL,event TEXT,action TEXT NOT NULL,detail TEXT NOT NULL,created BIGINT NOT NULL);
CREATE INDEX IF NOT EXISTS games_scores ON games(series,completed,winner,p1,p2);
ALTER TABLE jobs ADD COLUMN IF NOT EXISTS started_at BIGINT;
ALTER TABLE jobs ADD COLUMN IF NOT EXISTS finished_at BIGINT;
ALTER TABLE games ADD COLUMN IF NOT EXISTS reason TEXT;
UPDATE games SET reason=result::jsonb->>'reason' WHERE result IS NOT NULL AND reason IS NULL;
CREATE INDEX IF NOT EXISTS jobs_event_finished ON jobs(event,kind,finished_at);
CREATE INDEX IF NOT EXISTS jobs_event_status ON jobs(event,status,created);
CREATE INDEX IF NOT EXISTS audit_event_created ON audit(event,created);
CREATE INDEX IF NOT EXISTS members_event_team ON members(event,team);
